import React, { ReactNode, forwardRef } from 'react';

import { FormFieldMessageItem } from './FormFieldMessageItem.js';
import { Flex } from '../../../../layouts-core/flex/Flex.js';
import { FormFieldControlMessage } from '../../contexts/FormFieldMessageContext.js';
import { useFormFieldMessagesContext } from '../../hooks/useFormFieldMessagesContext.js';

export type FormFieldMessageProps = {
  children?:
    | ((messages: FormFieldControlMessage[]) => ReactNode[] | ReactNode)
    | ReactNode;
};

/**
 * Component to display FormFieldMessages coming from the form control.
 */
export const _FormFieldMessages = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  FormFieldMessageProps
>((FormFieldMessageProps, forwardedRef) => {
  const { children, ...remainingProps } = FormFieldMessageProps;
  const { state } = useFormFieldMessagesContext();

  // if there is a render function we use this, otherwise we render children if any are provided
  // if no children are provided we render all form control messages
  return (
    <Flex ref={forwardedRef} {...remainingProps} flexDirection="column">
      {children
        ? typeof children === 'function'
          ? children(state.formControlMessages)
          : children
        : state.formControlMessages.map((message) => {
            return <FormFieldMessages.Item {...message} key={message.id} />;
          })}
    </Flex>
  );
});

(
  _FormFieldMessages as typeof _FormFieldMessages & {
    displayName: string;
  }
).displayName = 'FormFieldMessages';

export const FormFieldMessages = Object.assign(_FormFieldMessages, {
  Item: FormFieldMessageItem,
});
